CREATE TABLE IF NOT EXISTS {{lms_progress}} (site_id VARCHAR(128) NOT NULL, learner VARCHAR(80) NOT NULL, video_id VARCHAR(128) NOT NULL, session_id VARCHAR(64), seq INTEGER NOT NULL DEFAULT 0, segments LONGTEXT NOT NULL, position DOUBLE NOT NULL DEFAULT 0, duration DOUBLE, max_watched DOUBLE NOT NULL DEFAULT 0, watched_seconds DOUBLE NOT NULL DEFAULT 0, percent INTEGER NOT NULL DEFAULT 0, active_seconds DOUBLE NOT NULL DEFAULT 0, completed_at VARCHAR(32), reported_at INTEGER, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, PRIMARY KEY (site_id, learner, video_id), UNIQUE (site_id, video_id, learner)) {{options}};
CREATE TABLE IF NOT EXISTS {{lms_notes}} (site_id VARCHAR(128) NOT NULL, id VARCHAR(16) NOT NULL, learner VARCHAR(80) NOT NULL, video_id VARCHAR(128) NOT NULL, kind VARCHAR(16) NOT NULL, time_seconds DOUBLE NOT NULL, text TEXT NOT NULL, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, deleted_at VARCHAR(32), PRIMARY KEY (site_id, id), UNIQUE (site_id, learner, video_id, id)) {{options}};
